// Harness for exercise 00. You do not edit this file.
//
// It does three things:
//   1. reports the machine, so you can fill in the roofline worksheet
//   2. measures real streaming bandwidth (the ceiling every later gate uses)
//   3. checks your write_indices kernel

#include <cstdio>
#include <vector>

#include "bench.cuh"
#include "kernel.cu"

int main(int argc, char** argv) {
    int n = (argc > 1) ? std::atoi(argv[1]) : 1000003;  // deliberately prime

    bench::Gate gate("00-hello-gpu");

    const bench::DeviceInfo& d = bench::device_info();
    double ceiling = bench::copy_ceiling_gbs();

    std::printf("measured copy  : %.1f GB/s  (%.0f%% of datasheet %.0f GB/s)\n",
                ceiling, 100.0 * ceiling / d.peak_bw_gbs(), d.peak_bw_gbs());
    std::printf("---------------------------------------------\n");
    std::printf("ROOFLINE WORKSHEET (fill this in by hand)\n");
    std::printf("  B  = %.1f GB/s   <- measured, use this everywhere\n", ceiling);
    std::printf("  P  = ______ TFLOP/s fp32   (look up your GPU)\n");
    std::printf("  I* = P / B = ______ FLOPs per byte\n");
    std::printf("  A vector add has I = 0.083. How far below the knee is it?\n");
    std::printf("  What fraction of peak FLOPs can it ever reach?\n");
    std::printf("---------------------------------------------\n");

    // --- the actual test -------------------------------------------------
    int* d_out = nullptr;
    CUDA_CHECK(cudaMalloc(&d_out, n * sizeof(int)));
    CUDA_CHECK(cudaMemset(d_out, 0xFF, n * sizeof(int)));  // poison: -1 everywhere

    launch_write_indices(d_out, n);
    CUDA_CHECK_LAUNCH();

    std::vector<int> h(n);
    CUDA_CHECK(cudaMemcpy(h.data(), d_out, n * sizeof(int), cudaMemcpyDeviceToHost));
    CUDA_CHECK(cudaFree(d_out));

    std::vector<float> got(n), want(n);
    for (int i = 0; i < n; ++i) {
        got[i] = static_cast<float>(h[i]);
        want[i] = static_cast<float>(i);
    }

    bench::ErrorStats s = bench::compare(got, want, 0.0);
    gate.correctness(s, 0.0);
    if (s.first_bad != static_cast<size_t>(-1)) {
        std::printf("                 (a value of -1 means no thread ever wrote there)\n");
    }
    gate.no_perf_gate();
    return gate.finish();
}
